"""Failures are generated by local fixtures; SDK/transport never reaches network."""
import asyncio,json
import pytest
from sqlalchemy import select
from sqlalchemy.exc import OperationalError
from app.config import Settings
from app.db import Base,database,LLMExecution,LLMConfiguration
from app.llm_reliability import Reliability,category
from app.providers import MockProvider,ProviderError,Reply
from app.profiling import Profile
from app.rag_answers import grounded_result

@pytest.fixture
def layer(tmp_path):
 s=Settings(_env_file=None,database_url=f'sqlite:///{tmp_path/"fault.db"}');engine,sessions=database(s.database_url);Base.metadata.create_all(engine);l=Reliability(sessions,s,MockProvider());l.seed();return l

def call(l):return asyncio.run(l.execute({'instructions':'data','tools':[]},[{'role':'user','parts':[{'text':'local'}]}],128))
@pytest.mark.parametrize('reply',[Reply(),Reply(text=123),Reply(text='invalid',input_tokens=-1)])
def test_invalid_or_empty(layer,reply):
 class Bad(MockProvider):
  async def generate(self,*a):return reply
 layer.adapter=Bad()
 with pytest.raises(ProviderError,match='invalid_response'):call(layer)
 with layer.sessions() as db:assert db.scalar(select(LLMExecution)).status=='failed'

def test_malformed_structured_output():
 with pytest.raises(ProviderError,match='invalid_rag_output'):grounded_result('{bad json',{'query':'q','matches':[]},'mock')

def test_trace_failure_fail_closed_with_emergency_audit(layer,monkeypatch,tmp_path):
 from sqlalchemy.orm import Session
 monkeypatch.setattr(Session,'commit',lambda s: (_ for _ in ()).throw(OperationalError('hidden statement',{},Exception('secret diagnostic'))))
 with pytest.raises(ProviderError,match='trace_persistence_failed'):call(layer)
 data=(tmp_path/'fault.audit.jsonl').read_text();assert 'trace_persistence_failed' in data;assert 'secret diagnostic' not in data;assert 'hidden statement' not in data

def test_sqlite_lock_keeps_error_audit(layer):
 import sqlite3
 with layer.sessions() as db:db.execute(__import__('sqlalchemy').text('PRAGMA busy_timeout=20'));db.commit()
 connection=sqlite3.connect(layer.sessions.kw['bind'].url.database);connection.execute('BEGIN IMMEDIATE')
 try:
  with pytest.raises(ProviderError,match='trace_persistence_failed'):call(layer)
 finally:connection.rollback();connection.close()

def test_trace_optimization_counts(layer):
 # Warm the persistent breaker once; default path still durably stores queued/running/final.
 call(layer);p=Profile().start()
 try:r=call(layer);counts=p.snapshot()['counts'];assert counts['commits']==3;assert counts['sqlite_writes']==3
 finally:p.stop()
 with layer.sessions() as db:assert db.get(LLMExecution,r.request_id).status=='success'

def test_partial_streaming_is_explicitly_unsupported():
 # No API can select streaming; never label a partial stream as a completed answer.
 from app.llm_api import ModelEntry
 with pytest.raises(__import__('pydantic').ValidationError):ModelEntry(provider='gemini',model='fixture',display_name='fixture',streaming=True)
